        "kpi1  kpi2  kpi3  kpi4"
        "chart chart chart live"
        "pages pages pages pages";
}

@media (max-width: 1100px) {
    .sa-dashboard-grid--overview {
        grid-template-columns: repeat(2, 1fr);
        grid-template-areas:
            "kpi1  kpi2"
            "kpi3  kpi4"
            "chart chart"
            "live  live"
            "pages pages";
    }
}

@media (max-width: 620px) {
    .sa-dashboard-grid--overview {
        grid-template-columns: 1fr;
        grid-template-areas:
            "kpi1" "kpi2" "kpi3" "kpi4"
            "chart" "live" "pages";
    }
}

/* ── Audience sub-page grid ──────────────────────────────────────────────────── */

.sa-audience-grid {
    display: grid;
    gap: 12px;
    align-items: start;
    grid-template-columns: repeat(2, 1fr);
    grid-template-areas:
        "countries  countries"
        "browsers   os"
        "screens    devices"
        "lang       tz";
}

.sa-aud-countries { grid-area: countries; }
.sa-aud-browsers  { grid-area: browsers;  }
.sa-aud-os        { grid-area: os;        }
.sa-aud-devices   { grid-area: devices;   }
.sa-aud-screens   { grid-area: screens;   }
.sa-aud-lang      { grid-area: lang;      }
.sa-aud-tz        { grid-area: tz;        }

@media (max-width: 620px) {
    .sa-audience-grid {
        grid-template-columns: 1fr;
        grid-template-areas:
            "countries" "browsers" "os"
            "devices" "screens" "lang" "tz";
    }
}

/* ── Acquisition sub-page grid ───────────────────────────────────────────────── */

.sa-acq-grid {
    display: grid;
    gap: 12px;
    align-items: start;
    grid-template-columns: repeat(2, 1fr);
    grid-template-areas: "pages utm";
}

.sa-acq-pages { grid-area: pages; }
.sa-acq-utm   { grid-area: utm;   }

@media (max-width: 760px) {
    .sa-acq-grid {
        grid-template-columns: 1fr;
        grid-template-areas: "pages" "utm";
    }
}

/* ── Consent sub-page grid ───────────────────────────────────────────────────── */

.sa-consent-page-grid {
    display: grid;
    gap: 12px;
    align-items: start;
    grid-template-columns: repeat(4, 1fr);
    grid-template-areas:
        "kpi1 kpi2 kpi3 kpi4"
        "bars bars bars bars";
}

.sa-cg-kpi1 { grid-area: kpi1; }
.sa-cg-kpi2 { grid-area: kpi2; }
.sa-cg-kpi3 { grid-area: kpi3; }
.sa-cg-kpi4 { grid-area: kpi4; }
.sa-cg-bars { grid-area: bars; }

@media (max-width: 1100px) {
    .sa-consent-page-grid {
        grid-template-columns: repeat(2, 1fr);
        grid-template-areas:
            "kpi1 kpi2"
            "kpi3 kpi4"
            "bars bars";
    }
}

@media (max-width: 620px) {
    .sa-consent-page-grid {
        grid-template-columns: 1fr;
        grid-template-areas:
            "kpi1" "kpi2" "kpi3" "kpi4" "bars";
    }
}

/* ── Heatmap sub-page grid ───────────────────────────────────────────────────── */

.sa-heatmap-grid {
    display: grid;
    gap: 12px;
    align-items: start;
    grid-template-columns: 2fr 1fr;
    grid-template-areas:
        "controls controls"
        "viewport scroll"
        "viewport elements";
}

.sa-heatmap__controls { grid-area: controls; display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.sa-heatmap__viewport { grid-area: viewport; }
.sa-heatmap__scroll   { grid-area: scroll;   }
.sa-heatmap__elements { grid-area: elements; }

@media (max-width: 900px) {
    .sa-heatmap-grid {
        grid-template-columns: 1fr;
        grid-template-areas: "controls" "viewport" "scroll" "elements";
    }
}

.sa-select {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 8px;
    color: rgba(220,220,220,0.9);
    font-size: 0.82rem;
    padding: 7px 10px;
    min-width: 220px;
}

.sa-heatmap__device-tabs {
    display: flex;
    gap: 4px;
    background: rgba(255,255,255,0.04);
    border-radius: 8px;
    padding: 3px;
}

.sa-heatmap__device-tab {
    background: transparent;
    border: none;
    color: rgba(180,180,180,0.7);
    font-size: 0.76rem;
    padding: 6px 12px;
    border-radius: 6px;
    cursor: pointer;
}

.sa-heatmap__device-tab.--active {
    background: rgba(192,159,83,0.18);
    color: rgba(230,210,160,0.95);
}

.sa-heatmap__frame-wrap {
    position: relative;
    width: 100%;
    aspect-ratio: 4 / 3;
    border-radius: 10px;
    overflow: hidden;
    background: rgba(0,0,0,0.25);
    border: 1px solid rgba(255,255,255,0.06);
}

.sa-heatmap__frame {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    border: none;
    pointer-events: none;
}

.sa-heatmap__frame-fallback {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 24px;
    font-size: 0.8rem;
    color: rgba(150,150,150,0.6);
}

.sa-heatmap__overlay {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
}

.sa-scroll-funnel {
    display: flex;
    flex-direction: column;
    gap: 9px;
}
